zed.nix:1:{ config, lib, pkgs, machine, nixgl, system, ... }:
zed.nix:5:  isDesktop = machine.gui or true;
home.nix:15:  machine,
home.nix:23:  hostname = machine.hostname;
home.nix:24:  isDesktop = machine.gui or true;
home.nix:25:  gpu = machine.gpu or null;
home.nix:78:    # gecko. Still skipped on macOS, as under firefox; that path has never
home.nix:147:  # Emacs is NOT part of the desktop stack: it runs headless as a daemon and is
home.nix:148:  # reached over tty/SSH with `emacsclient -t` (zsh.nix's non_gui branch already
home.nix:150:  # build by isDesktop rather than dropping emacs on headless hosts — dropping it
home.nix:152:  # Unversioned: nixpkgs retired the emacs30-* aliases in August 2026.
home.nix:153:  emacsPkg = if isDesktop then pkgs.emacs-pgtk else pkgs.emacs-nox;
home.nix:773:  # keyring file is useless off this machine -- nothing more. Prompts stop
home.nix:779:  # it was decryptable by a cloud KMS from anywhere, so "off this machine" bought
home.nix:910:    # "useless off this machine" claim above false -- one KMS-decryptable value
home.nix:974:        ${pkgs.coreutils}/bin/mv "$KEYRINGS/$f" "$KEYRINGS/$f.superseded-$stamp"
home.nix:975:        echo "gnome-keyring-tpm-seal: moved $f aside as $f.superseded-$stamp (nothing can read it now)"
home.nix:2326:  # $USER/$HOME differ declare it in their `machine` attrset.
home.nix:2328:    machine.username or (let v = builtins.getEnv "USER"; in if v != "" then v else "sauyon");
home.nix:2330:    machine.homeDir or (
home.nix:2395:  # ── Emacs ──────────────────────────────────────────────────────────────────
home.nix:2396:  home.file.".emacs.d/init.el".source = ./home/emacs/init.el;
home.nix:2397:  home.file.".emacs.d/lisp/mode-init.el".source = ./home/emacs/lisp/mode-init.el;
home.nix:2398:  home.file.".emacs.d/lisp/pref-init.el".source = ./home/emacs/lisp/pref-init.el;
home.nix:2399:  home.file.".emacs.d/lisp/root-find.el".source = ./home/emacs/lisp/root-find.el;
home.nix:2402:  home.file.".emacs.d/lisp/grip-path.el" = lib.mkIf (!isDarwin) {
home.nix:2408:  services.emacs = lib.mkIf (!isDarwin) {
home.nix:2410:    package = withHostNss emacsPkg;
home.nix:3167:    # what macOS does not already ship or ships in a form worth replacing; the
home.nix:3198:    (emacsPackages.treesit-grammars.with-grammars (grammars: with grammars; [
home.nix:3205:    # The rest of the network tools (see the list above). macOS answers route,
home.nix:3238:    # Headless hosts get the -nox build; see emacsPkg. Deliberately outside the
home.nix:3240:    # emacsclient, so gating this on the desktop stack breaks editing over SSH.
home.nix:3242:    # withHostNss, not bare: an unwrapped nix emacs can't dlopen the host's
home.nix:3244:    # no /etc/passwd entry. Emacs then sets init-file-user to "sauyon" instead
home.nix:3246:    # home directory" (startup.el's file-directory-p check). services.emacs
home.nix:3248:    (withHostNss emacsPkg)
home.nix:3469:        # nixpkgs cherry-picks an upstream macOS compile fix already in our base
home.nix:3550:    gtk3.extraConfig.gtk-key-theme-name = "Emacs";
home.nix:3552:      @binding-set mac-bindings {
home.nix:3553:        bind "<Super>x" { "cut-clipboard" () };
home.nix:3554:        bind "<Super>c" { "copy-clipboard" () };
home.nix:3555:        bind "<Super>v" { "paste-clipboard" () };
home.nix:3556:        bind "<Super>a" { "select-all" (true) };
home.nix:3557:        bind "<Super>z" { "undo" () };
home.nix:3558:        bind "<Super><Shift>z" { "redo" () };
home.nix:3560:      * { -gtk-key-bindings: mac-bindings; }
home.nix:3562:    gtk4.extraConfig.gtk-key-theme-name = "Emacs";
home.nix:3564:      @binding-set mac-bindings {
home.nix:3565:        bind "<Super>x" { "cut-clipboard" () };
home.nix:3566:        bind "<Super>c" { "copy-clipboard" () };
home.nix:3567:        bind "<Super>v" { "paste-clipboard" () };
home.nix:3568:        bind "<Super>a" { "select-all" (true) };
home.nix:3569:        bind "<Super>z" { "undo" () };
home.nix:3570:        bind "<Super><Shift>z" { "redo" () };
home.nix:3572:      * { -gtk-key-bindings: mac-bindings; }
home.nix:3831:  # home-manager's "mesa" default this silently ignored machine.gpu, so a
home.nix:4333:      # default is the path Zen actually opens. macOS gets ~/Library/Application
home.nix:4477:        # omacom/omarchy#12917, which names herdr as the trigger.
home.nix:4507:          "performable:super+c=copy_to_clipboard"
