mkdir -p /tmp/claude-1000/-home-sauyon-devel-dotfiles/9ba483e0-4eab-46f1-a189-99a5f9fcee3e/scratchpad/gen && cat > /tmp/claude-1000/-home-sauyon-devel-dotfiles/9ba483e0-4eab-46f1-a189-99a5f9fcee3e/scratchpad/gen/gen.js <<'EOF'
const path = require('path');
const [shared, chordsFile] = process.argv.slice(2);
const kb = require(path.join(shared, 'keybindings.js'));
const chords = JSON.parse(require('fs').readFileSync(chordsFile, 'utf8'));
const MOD = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
const KEY = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
const taken = new Set();
for (const c of chords) {
  const parts = c.split('+').map(s => s.trim());
  const key = parts.pop();
  if (!parts.every(p => MOD[p.toUpperCase()])) continue;
  const n = kb.normalizeKeybinding([...parts.map(p => MOD[p.toUpperCase()]), KEY[key] ?? key].join('+'));
  if (n.ok) taken.add(n.value);
}
const overrides = {}, dropped = {};
for (const d of kb.KEYBINDING_DEFINITIONS) {
  const mac = kb.getDefaultBindings(d, 'darwin').map(b => b.split('+').map(t => t === 'Mod' ? 'Cmd' : t).join('+'));
  const norm = mac.map(b => { const n = kb.normalizeKeybindingWithOptions(b, kb.normalizeOptionsForAction(d.id)); if (!n.ok) throw new Error(`${d.id}: ${b}: ${n.error}`); return n.value; });
  const free = norm.filter(b => !taken.has(b));
  if (free.length < norm.length) dropped[d.id] = norm.filter(b => taken.has(b));
  if (norm.length > 0 && free.length === 0) continue;
  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(d, 'linux'))) continue;
  overrides[d.id] = free;
}
const conflicts = kb.findKeybindingConflicts('linux', overrides);
console.error(JSON.stringify({ dropped, conflicts }, null, 1));
console.log(JSON.stringify(overrides, null, 2));
EOF
